#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Self-test for tests/check_nsi_file_globs.sh. Each case builds a throwaway
# checkout with its own `installer/installer.nsi` and asserts the exit code
# together with the printed line, so the four rules the check claims (relative
# path base, `*.*` = every entry, `/x` and `/oname=` are not paths, a
# `.gitignore`d path is build output) are pinned instead of remembered.
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.
set -u

. "${BASH_SOURCE[0]%/*}/gate_lib.sh"

gate_top
GATE="$ROOT/tests/check_nsi_file_globs.sh"
[ -f "$GATE" ] || { echo "self-test: gate not found at $GATE" >&2; exit 2; }

gate_sandbox pime-nsi-globs-selftest || { echo "self-test: no sandbox" >&2; exit 2; }
SANDBOX=$tmp

failures=0
out=''
rc=0
run_gate() { # dir
    out=$( cd "$1" && bash "$GATE" 2>&1 )
    rc=$?
}
check() { # name want
    if [ "$2" = "$rc" ]; then
        printf 'ok    %s (rc %s)\n' "$1" "$rc"
    else
        printf 'FAIL  %s: want rc %s, got rc %s | %s\n' "$1" "$2" "$rc" "$out"
        failures=$((failures + 1))
    fi
}
expect() { # name needle
    if printf '%s\n' "$out" | grep -qF -e "$2"; then
        printf 'ok    %s\n' "$1"
    else
        printf 'FAIL  %s: no line holding %s | %s\n' "$1" "$2" "$out"
        failures=$((failures + 1))
    fi
}

new_repo() { # name — a committed tree holding installer/installer.nsi on stdin
    local dir="$SANDBOX/$1"
    mkdir -p "$dir/installer" || return 1
    cat > "$dir/installer/installer.nsi" || return 1
    [ -f "$dir/.gitignore" ] || : > "$dir/.gitignore"
    ( cd "$dir" && git init -q . && git add -A \
        && git -c user.email=a@b -c user.name=a commit -qm t ) >/dev/null 2>&1 || return 1
    printf '%s' "$dir"
}

# 1. Every directive resolves; the CRLF line endings of the real script are kept.
d=$(new_repo ok <<'EOF'
Section "x"
    File "..\version.txt"
    File /r /x "brise" "..\python\rimebase\*.*"
    File /r /x "nope*" "..\python\input_methods\rime\*.json"
SectionEnd
EOF
) || { echo "self-test: sandbox init failed" >&2; exit 2; }
mkdir -p "$d/python/rimebase" "$d/python/input_methods/rime"
printf 'v\n' > "$d/version.txt"
printf 'e\n' > "$d/python/rimebase/rime_service.py"
printf '{}\n' > "$d/python/input_methods/rime/ime.json"
( cd "$d" && git add -A && git -c user.email=a@b -c user.name=a commit -qm files ) >/dev/null 2>&1
run_gate "$d"
check "resolving tree" 0
expect "names the count" 'nsi File globs resolve'

# 2. A glob with no match is the red makensis aborts on.
( cd "$d" && rm python/input_methods/rime/ime.json && printf 'x\n' > python/input_methods/rime/only.txt \
    && git add -A && git -c user.email=a@b -c user.name=a commit -qm txt ) >/dev/null 2>&1
run_gate "$d"
check "a *.json glob with no match" 1
expect "points at the directive" 'installer/installer.nsi:4: no files found for ..\python\input_methods\rime\*.json'

# 3. `*.*` reaches an entry with no dot, as NSIS expands it.
d=$(new_repo dotless <<'EOF'
    File "..\data\*.*"
EOF
) || { echo "self-test: sandbox init failed" >&2; exit 2; }
mkdir -p "$d/data" && printf 'n\n' > "$d/data/NOTICE"
( cd "$d" && git add -A && git -c user.email=a@b -c user.name=a commit -qm notice ) >/dev/null 2>&1
run_gate "$d"
check "*.* matches a dotless name" 0

# 4. An option value is not a path: the unmatched /x pattern stays silent.
d=$(new_repo options <<'EOF'
    File /r /x "webpack_check.js" /oname=index.js "..\node\emojime\ime.json"
EOF
) || { echo "self-test: sandbox init failed" >&2; exit 2; }
mkdir -p "$d/node/emojime" && printf '{}\n' > "$d/node/emojime/ime.json"
( cd "$d" && git add -A && git -c user.email=a@b -c user.name=a commit -qm json ) >/dev/null 2>&1
run_gate "$d"
check "options are not paths" 0
expect "checked exactly one path" '(1 path(s) checked)'

# 5. A `.gitignore`d path is build output, answered by build.bat.
d=$(new_repo generated <<'EOF'
    File "..\build\PIMELauncher\Release\PIMELauncher.exe"
    File "..\python\rimebase\*.*"
EOF
) || { echo "self-test: sandbox init failed" >&2; exit 2; }
printf 'build\n' > "$d/.gitignore"
mkdir -p "$d/python/rimebase" && printf 'e\n' > "$d/python/rimebase/librime.py"
( cd "$d" && git add -A && git -c user.email=a@b -c user.name=a commit -qm ign ) >/dev/null 2>&1
run_gate "$d"
check "ignored build output skipped" 0
expect "only the tracked path counted" '(1 path(s) checked)'

# 6. Two specs on one line: the second one missing still reddens the run.
d=$(new_repo pair <<'EOF'
    File "..\python\opencc\*.json" "..\python\opencc\*.ocd"
EOF
) || { echo "self-test: sandbox init failed" >&2; exit 2; }
mkdir -p "$d/python/opencc" && printf '{}\n' > "$d/python/opencc/s2t.json"
( cd "$d" && git add -A && git -c user.email=a@b -c user.name=a commit -qm json ) >/dev/null 2>&1
run_gate "$d"
check "second spec of a line" 1
expect "names the missing glob" 'no files found for ..\python\opencc\*.ocd'

# 7. No script at all: not applicable.
d2="$SANDBOX/noscript"; mkdir -p "$d2"
( cd "$d2" && git init -q . && : > README && git add -A \
    && git -c user.email=a@b -c user.name=a commit -qm t ) >/dev/null 2>&1
run_gate "$d2"
check "no installer script" 125
expect "says why" 'installer/installer.nsi missing'

if [ "$failures" -ne 0 ]; then
    printf 'Self-test failed (%d case(s))\n' "$failures" >&2
    exit 1
fi
echo "Self-test passed"
